    @Override public void onCreate(Bundle state){super.onCreate(state);store=new Store(this);api=new Api(store);if(store.token("access_token").isEmpty())loginPage();else home();handler.post(tick);}
    @Override public void onResume(){super.onResume();foreground=true;if(store!=null&&getIntent().hasExtra("recording_id")&&!store.token("access_token").isEmpty()){String id=getIntent().getStringExtra("recording_id");getIntent().removeExtra("recording_id");detail(id);return;}if(store!=null&&getIntent().getBooleanExtra("open_recording",false)&&(RecorderService.active||RecorderService.finishing)){getIntent().removeExtra("open_recording");showRecorder();}else if(store!=null&&page.equals("home")&&!loading)loadHome(false);}
