    @Override public void onBackPressed(){if(page.equals("home")||page.equals("login")){super.onBackPressed();return;}if(page.equals("chat")){chats();return;}home();}
    final Runnable tick=new Runnable(){public void run(){
        if(foreground){
            if(page.equals("record")){if(timer!=null)timer.setText(clock(RecorderService.elapsed()));updateLive();if(!RecorderService.active&&!RecorderService.finishing&&timer!=null){timer=null;saveRecording(RecorderService.draftId);}}
            if(player!=null&&playerReady&&seek!=null)try{if(!seeking){seek.setProgress(player.getCurrentPosition());if(playStatus!=null)playStatus.setText(clock(player.getCurrentPosition())+" / "+clock(player.getDuration()));}}catch(Exception ignored){}
            if(SystemClock.elapsedRealtime()-lastPoll>5000&&(dialog==null||!dialog.isShowing())&&!loading){lastPoll=SystemClock.elapsedRealtime();if(page.equals("home")&&!(getCurrentFocus() instanceof EditText)&&(hasPendingRecords()||TransferService.active||lastTransferActive)){lastTransferActive=TransferService.active;loadHome(false);}else if(page.equals("detail")&&(!currentRecord.optString("status").equals("transcribed")||currentSummaries.length()==0)&&!detailTab.equals("Mind map"))loadDetail(false);}
        }handler.postDelayed(this,1000);
    }};
