    void addNav(String title,Runnable action,boolean active){
        LinearLayout item=column();item.setGravity(Gravity.CENTER);item.setPadding(dp(4),dp(8),dp(4),dp(6));item.setMinimumHeight(dp(56));
        String name=title.equals("Library")?"files":title.equals("Ask")?"messages_square":title.equals("Tasks")?"list_checks":"user_round";
        ImageView image=icon(name,active?INK:MUTED);image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        item.addView(image,new LinearLayout.LayoutParams(dp(22),dp(22)));
        TextView label=text(title,11,active?INK:MUTED);label.setGravity(Gravity.CENTER);label.setIncludeFontPadding(false);label.setSingleLine(true);label.setLineSpacing(0,1);
        label.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        LinearLayout.LayoutParams caption=new LinearLayout.LayoutParams(-1,-2);caption.topMargin=dp(4);item.addView(label,caption);
        item.setContentDescription(title);item.setSelected(active);item.setFocusable(true);item.setOnClickListener(v->action.run());
        // Natural height keeps enlarged system text inside the same tap target.
        nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));
    }
    <T> void task(String message,Work<T> work,Result<T> result){
        int version=generation;loading=true;if(status!=null)status.setText(message);
        pendingOperations.incrementAndGet();
        io.execute(()->{
            try{T value=work.run();handler.post(()->{if(isDestroyed()||version!=generation)return;loading=false;status.setText("");try{result.done(value);}catch(Exception e){error(e);}});}
            catch(Exception e){handler.post(()->{if(isDestroyed()||version!=generation)return;loading=false;status.setText("Could not finish · "+friendly(e));if(!message.isEmpty())error(e);});}
            finally{pendingOperations.decrementAndGet();}
        });
    }
    String friendly(Exception e){if(e instanceof java.net.UnknownHostException)return "Cannot reach the server. Check your connection and server address.";if(e instanceof java.net.SocketTimeoutException)return "The request timed out. Local recordings are kept; try again.";return e.getMessage()==null?"Action failed. Try again.":e.getMessage();}
    void error(Exception e){if(e instanceof Api.Failure&&((Api.Failure)e).status==401){if(RecorderService.active||RecorderService.finishing||TransferService.active||JwdService.active){alert("Session expired","Finish recording or uploading before signing in again. Local recordings are kept.",null);return;}alert("Sign-in required","Local recordings are kept. Sign in to the same account to continue.",()->{store.logout();loginPage();});}else alert("Action not completed",friendly(e),null);}
    void alert(String title,String message,Runnable then){dialog=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("OK",(d,w)->{if(then!=null)then.run();}).show();}
    void confirm(String title,String message,Runnable yes){dialog=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->yes.run()).show();}
    JSONObject json(Object... values){JSONObject o=new JSONObject();try{for(int i=0;i<values.length;i+=2)o.put((String)values[i],values[i+1]);}catch(Exception e){throw new IllegalArgumentException(e);}return o;}
    String str(JSONObject o,String k){return o==null||o.isNull(k)?"":o.optString(k);}
    JSONArray arr(JSONObject o,String k){JSONArray a=o.optJSONArray(k);return a==null?new JSONArray():a;}
    static String clock(long ms){long s=Math.max(0,ms)/1000;return String.format(Locale.ROOT,"%02d:%02d",s/60,s%60);}
    String date(String iso){try{return OffsetDateTime.parse(iso).atZoneSameInstant(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("MMM d, HH:mm",Locale.US));}catch(Exception e){return iso;}}
    String state(String s){switch(s){case "uploaded":case "queued":return "Queued";case "running":case "transcribing":return "Transcribing";case "transcribed":return "Transcript ready";case "transcription_failed":case "failed":return "Processing failed";case "interrupted":return "Interrupted · Retry available";case "completed":return "Completed";case "processing":return "Processing";case "uploading":return "Uploading";case "invalid":return "Recording interrupted";default:return "Saved on phone";}}

    void loginPage(){
        selected.clear();records=new JSONArray();folderFilter="";tagFilter="";searchTerm="";releasePlayer();begin("login","Sign in","");gap(content,34);content.addView(bold("teno.",46,INK));gap(content,28);content.addView(bold("Meeting notes and tasks",25,INK));gap(content,8);content.addView(text("Record conversations, review transcripts and manage follow-up work.",15,MUTED));gap(content,20);
        LinearLayout c=card(content);EditText username=input(c,"Username",store.name(),false);EditText password=input(c,"Password","",false);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);gap(c,16);c.addView(button("Sign in",true,()->{if(loading)return;String u=username.getText().toString().trim(),p=password.getText().toString();if(u.isEmpty()||p.isEmpty()){alert("Enter your account details","Use the account provided by your administrator.",null);return;}task("Signing in…",()->{api.login(u,p);return true;},v->{password.setText("");home();});}));gap(content,18);content.addView(button("Join with an invitation",false,()->startActivity(new Intent(this,TeamActivity.class).putExtra("activate",true))));gap(content,8);content.addView(button("Test a recorder without signing in",false,this::devices));gap(content,20);TextView server=text("Server settings",13,MUTED);server.setOnClickListener(v->serverSettings(true));content.addView(server);
    }
    void home(){if(!store.nativePreferencesSet()&&!store.scope().isEmpty()){pendingOperations.incrementAndGet();io.execute(()->{try{api.ensureNativePreferences();}catch(Exception ignored){}finally{pendingOperations.decrementAndGet();}});}store.recoverRecordings();begin("home","Recordings","");renderHome();loadHome(true);}
    void renderHome(){
        content.removeAllViews();content.addView(bold("Recordings",28,INK));gap(content,16);
        TextView device=button("Recorder device",false,this::devices);device.setCompoundDrawablesWithIntrinsicBounds(R.drawable.ic_bluetooth,0,0,0);content.addView(device);gap(content,12);
        buttons(content,folderFilter.isEmpty()?"All folders":"Clear folder",()->{if(!folderFilter.isEmpty()){folderFilter="";loadHome(true);}else chooseResource("folders","Choose folder",true,id->{folderFilter=id;loadHome(true);});},tagFilter.isEmpty()?"Tags":"Clear tag",()->{if(!tagFilter.isEmpty()){tagFilter="";loadHome(true);}else chooseResource("tags","Choose tag",true,id->{tagFilter=id;loadHome(true);});});
        if(!searchTerm.isEmpty()){content.addView(text("Search: "+searchTerm,13,MUTED));content.addView(button("Clear search",false,()->{searchTerm="";loadHome(true);}));}
        if(TransferService.active){LinearLayout c=card(content);c.addView(text(TransferService.message,14,INK));}
        JSONArray drafts=store.drafts();boolean any=false;
        for(int i=0;i<drafts.length();i++){JSONObject d=drafts.optJSONObject(i);if(d==null||!str(d,"recording_id").isEmpty()||d.optString("status").equals("recording")&&(RecorderService.active||RecorderService.finishing))continue;
            if(!any){label(content,"Saved on phone");any=true;}LinearLayout c=card(content);c.addView(bold(d.optString("title"),17,INK));c.addView(text(date(d.optString("created_at"))+" · "+state(d.optString("status")),12,MUTED));if(!str(d,"error").isEmpty())c.addView(text(d.optString("error"),12,RED));buttons(c,"Review and upload",()->saveRecording(d.optString("id")),"Play audio",()->playLocal(d));}
        label(content,"Recent recordings");
        if(!selected.isEmpty())buttons(content,"Ask about "+selected.size(),()->createChat(new ArrayList<>(selected)),"Generate insights",()->generateSelected("insights"));
        if(records.length()==0){LinearLayout empty=card(content);empty.addView(bold(searchTerm.isEmpty()?"No recordings yet":"No recordings found",18,INK));gap(empty,6);empty.addView(text("Record or import audio to view its transcript and summary here.",14,MUTED));}
        for(int i=0;i<records.length();i++){JSONObject rec=records.optJSONObject(i);if(rec==null)continue;LinearLayout c=card(content),r=row();
            if(selectionMode){CheckBox check=new CheckBox(this);check.setChecked(selected.contains(rec.optString("id")));check.setContentDescription("Select "+rec.optString("title"));check.setOnCheckedChangeListener((b,on)->{if(on)selected.add(rec.optString("id"));else selected.remove(rec.optString("id"));renderHome();});r.addView(check);}else{ImageView ic=icon("file_audio",INK);ic.setPadding(dp(8),dp(8),dp(8),dp(8));ic.setBackground(shape(PALE,12));r.addView(ic,new LinearLayout.LayoutParams(dp(40),dp(40)));}
            LinearLayout titles=column();titles.setPadding(dp(12),0,dp(8),0);titles.addView(bold(rec.optString("title","Untitled recording"),16,INK));gap(titles,5);titles.addView(text(date(rec.optString("created_at"))+" · "+clock(rec.optLong("duration_ms"))+" · "+state(rec.optString("status")),12,MUTED));r.addView(titles,new LinearLayout.LayoutParams(0,-2,1));r.addView(icon("chevron_right",MUTED),new LinearLayout.LayoutParams(dp(18),dp(18)));c.addView(r);c.setOnClickListener(v->detail(rec.optString("id")));c.setOnLongClickListener(v->{selectionMode=true;selected.add(rec.optString("id"));renderHome();return true;});}
        gap(content,20);content.addView(button(RecorderService.active||RecorderService.finishing?"Return to recording":"Start recording",true,this::recordPage));gap(content,10);content.addView(button("Import audio",false,()->pick("audio")));gap(content,12);TextView refresh=text("Refresh library",13,MUTED);refresh.setOnClickListener(v->loadHome(true));content.addView(refresh);
    }
    void loadHome(boolean visible){
        if(store.token("access_token").isEmpty()){loginPage();return;}if(loading)return;
        task(visible?"Syncing recordings…":"",()->{
            if(!searchTerm.isEmpty()){JSONArray found=arr(api.get("/api/v1/search?q="+Api.query(searchTerm)),"items");JSONArray list=new JSONArray();for(int i=0;i<found.length();i++)list.put(found.getJSONObject(i).getJSONObject("recording"));return list;}
            String query="?limit=100";if(!folderFilter.isEmpty())query+="&folder_id="+folderFilter;if(!tagFilter.isEmpty())query+="&tag_id="+tagFilter;return arr(api.get("/api/v1/recordings"+query),"items");
        },list->{records=list;renderHome();});
    }
    void uploadDraft(JSONObject draft){if(TransferService.active){alert("Uploading","Wait for the current upload to finish before starting another.",null);return;}try{startForegroundService(new Intent(this,TransferService.class).putExtra("id",draft.getString("id")));handler.postDelayed(this::home,400);}catch(Exception e){error(e);}}
    void recordPage(){
        if(RecorderService.finishing){showRecorder();return;}if(!RecorderService.active){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},100);return;}newRecording();return;}
        showRecorder();
    }
    void newRecording(){
        begin("setup","New recording","");content.addView(bold("Recording settings",27,INK));EditText title=input(content,"Title","Recording "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("MMM d, HH:mm",Locale.US)),false);
        label(content,"Audio source");Spinner source=new Spinner(this);source.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Phone microphone","Connected recorder"}));content.addView(source);
        label(content,"Transcription language");Spinner language=new Spinner(this);language.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Chinese (Mandarin)","English (US)"}));language.setSelection(store.language().equals("en-US")?1:0);content.addView(language);
        CheckBox liveCheck=new CheckBox(this);liveCheck.setText("Live transcription");liveCheck.setTextColor(INK);liveCheck.setChecked(getSharedPreferences("teno",0).getBoolean("live_default",true));gap(content,16);content.addView(liveCheck);LinearLayout notice=card(content);notice.setBackground(shape(PALE,18));notice.addView(text("Live transcription sends audio to the speech service while you record. A local audio copy is saved.",13,INK));
        gap(content,20);content.addView(button("Start recording",true,()->{store.language(language.getSelectedItemPosition()==1?"en-US":"zh-CN");if(source.getSelectedItemPosition()==1){startActivity(new Intent(this,JwdActivity.class).putExtra("start_live",liveCheck.isChecked()));return;}try{JSONObject draft=store.newDraft(title.getText().toString().trim().isEmpty()?"New recording":title.getText().toString(),".wav");draft.put("live",liveCheck.isChecked());store.save(draft);startForegroundService(new Intent(this,RecorderService.class).setAction("start").putExtra("id",draft.getString("id")));handler.postDelayed(()->{if(RecorderService.active)showRecorder();else alert("Recording did not start",RecorderService.error.isEmpty()?"Check microphone permission and try again.":RecorderService.error,null);},500);}catch(Exception e){error(e);}}));notificationPermission();
    }
    void showRecorder(){
        begin("record","Recording","");String title="New recording",notes="",language=store.language();try{JSONObject d=store.draft(RecorderService.draftId);title=d.optString("title");notes=d.optString("notes");language=d.optString("language");}catch(Exception ignored){}
        content.addView(bold(title,27,INK));gap(content,16);LinearLayout line=row();liveStatus=text("Recording",13,GREEN);line.addView(liveStatus,new LinearLayout.LayoutParams(0,-2,1));timer=bold(clock(RecorderService.elapsed()),19,INK);line.addView(timer);content.addView(line);gap(content,8);content.addView(text("Phone microphone · "+(language.equals("zh-CN")?"Chinese (Mandarin)":"English (US)"),13,MUTED));gap(content,25);
        LinearLayout transcript=column();ScrollView liveScroll=new ScrollView(this);liveScroll.addView(transcript);liveFinal=text("",17,INK);liveFinal.setTextIsSelectable(true);transcript.addView(liveFinal);livePartial=text("",16,MUTED);transcript.addView(livePartial);content.addView(liveScroll,new LinearLayout.LayoutParams(-1,dp(230)));gap(content,16);recordingNotes=input(content,"Notes",notes,true);
        LinearLayout controls=column();controls.setPadding(dp(22),dp(4),dp(22),dp(18));controls.setBackgroundColor(BG);root.addView(controls);buttons(controls,RecorderService.paused?"Resume":"Pause",()->{saveNotes();startService(new Intent(this,RecorderService.class).setAction("pause"));handler.postDelayed(this::showRecorder,150);},"Stop and save",()->{saveNotes();startService(new Intent(this,RecorderService.class).setAction("stop"));liveStatus.setText("Finishing transcript…");});
        gap(controls,8);recordingRetry=button("Retry transcription",false,()->startService(new Intent(this,RecorderService.class).setAction("retry_live")));controls.addView(recordingRetry);recordingRetry.setVisibility(RecorderService.live==null?View.GONE:View.VISIBLE);gap(content,16);content.addView(text("Audio is saved on this phone. Recording continues when the screen is locked.",12,MUTED));updateLive();
    }
    void saveNotes(){if(recordingNotes!=null&&RecorderService.active)try{JSONObject d=store.draft(RecorderService.draftId);d.put("notes",recordingNotes.getText().toString());store.save(d);}catch(Exception ignored){}}
    void notificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},101);}
    @Override public void onRequestPermissionsResult(int request,String[] names,int[] results){super.onRequestPermissionsResult(request,names,results);if(request==100){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)newRecording();else alert("Microphone permission required","Allow microphone access to record, or import an existing audio file.",null);}}

    void detail(String id){detailId=id;detailTab="Summary";currentRecord=new JSONObject();currentSummaries=new JSONArray();begin("detail","Recording","Summary, transcript and audio");loadDetail(true);}
    void loadDetail(boolean visible){if(loading)return;String id=detailId;task(visible?"Loading recording…":"",()->new JSONObject[]{api.get("/api/v1/recordings/"+id),api.get("/api/v1/recordings/"+id+"/transcriptions"),api.get("/api/v1/recordings/"+id+"/summaries")},data->{currentRecord=data[0];currentTranscript=data[1];currentSummaries=arr(data[2],"items");renderDetail();});}
    void renderDetail(){
        content.removeAllViews();LinearLayout top=card(content);top.addView(bold(currentRecord.optString("title"),23,INK));gap(top,5);top.addView(text(date(currentRecord.optString("created_at"))+" · "+clock(currentRecord.optLong("duration_ms"))+" · "+state(currentRecord.optString("status")),12,MUTED));
        buttons(top,"Play audio",()->playCloud(detailId,0),"Options",this::recordMenu);seek=new SeekBar(this);seek.setMax((int)Math.max(1,currentRecord.optLong("duration_ms")));top.addView(seek);playStatus=text("00:00 / "+clock(currentRecord.optLong("duration_ms")),12,MUTED);top.addView(playStatus);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean from){}public void onStartTrackingTouch(SeekBar b){seeking=true;}public void onStopTrackingTouch(SeekBar b){seeking=false;if(player!=null&&playerReady)player.seekTo(b.getProgress());else playCloud(detailId,b.getProgress());}});
        LinearLayout tabs=row();for(String name:new String[]{"Summary","Transcript","Mind map"}){TextView t=button(name,detailTab.equals(name),()->{detailTab=name;renderDetail();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(2),dp(10),dp(2),dp(8));tabs.addView(t,p);}content.addView(tabs);
        if(detailTab.equals("Summary")){
            if(currentSummaries.length()==0){LinearLayout c=card(content);c.addView(bold("Summary not ready",18,INK));c.addView(text("A summary is generated after transcription. You can leave this screen and return later.",14,MUTED));buttons(c,"Refresh",()->loadDetail(true),"Generate summary",()->generateRecord("summaries",null));}
            else{JSONObject entry=currentSummaries.optJSONObject(0),data=entry.optJSONObject("data");if(entry.optBoolean("stale"))content.addView(text("This summary uses an earlier transcript. Generate a new version to include your edits.",13,RED));LinearLayout c=card(content);c.addView(text("Summary",12,PRIMARY));gap(c,8);c.addView(bold(data.optString("title"),21,INK));gap(c,10);TextView summary=text(data.optString("summary"),16,INK);summary.setTextIsSelectable(true);c.addView(summary);label(c,"Key points");JSONArray points=arr(data,"key_points");for(int i=0;i<points.length();i++)c.addView(text("• "+points.optString(i),15,INK));JSONArray todos=arr(data,"action_items");if(todos.length()>0)label(c,"Action items");for(int i=0;i<todos.length();i++){JSONObject t=todos.optJSONObject(i);if(t!=null)c.addView(text("□ "+t.optString("title")+(str(t,"assignee").isEmpty()?"":" · "+t.optString("assignee")),15,INK));}buttons(c,"Ask about this recording",()->createChat(Collections.singletonList(detailId)),"View tasks",()->resources("tasks"));gap(c,10);c.addView(text("Review generated content against the transcript. Versions: "+currentSummaries.length()+"",11,MUTED));}
        }else if(detailTab.equals("Transcript")){
            JSONArray segments=arr(currentTranscript,"segments");if(segments.length()==0)content.addView(text("No transcript yet. Refresh the status or choose Transcribe again from Options.",14,MUTED));
            for(int i=0;i<segments.length();i++){JSONObject s=segments.optJSONObject(i);LinearLayout c=card(content);LinearLayout head=row();TextView time=bold("▶ "+clock(s.optLong("start_ms")),12,PRIMARY);time.setOnClickListener(v->playCloud(detailId,(int)s.optLong("start_ms")));head.addView(time,new LinearLayout.LayoutParams(0,-2,1));TextView edit=text("Edit",12,MUTED);edit.setOnClickListener(v->editSegment(s));head.addView(edit);c.addView(head);gap(c,8);TextView words=text(s.optString("text"),16,INK);words.setTextIsSelectable(true);c.addView(words);}
        }else{content.addView(button("Generate mind map",true,()->generateRecord("mindmap",null)));task("Loading mind map…",()->arr(api.get("/api/v1/recordings/"+detailId+"/mindmap"),"items"),items->{if(!detailTab.equals("Mind map"))return;if(items.length()==0){content.addView(text("Generate a mind map from this recording.",14,MUTED));return;}JSONObject data=items.optJSONObject(0).optJSONObject("data");MindMapView view=new MindMapView(this,data);LinearLayout c=card(content);c.addView(view,new LinearLayout.LayoutParams(-1,dp(Math.max(220,view.nodeCount()*58))));gap(content,10);content.addView(button("Export PNG",false,()->{try{Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(bitmap));ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);exportFile("Teno-mindmap.png","image/png",out.toByteArray());}catch(Exception e){error(e);}}));});}
        gap(content,16);content.addView(button("Refresh results",false,()->loadDetail(true)));
    }
    void recordMenu(){String[] options={"Rename","Move to folder","Edit tags","Change summary template","Transcribe again","Summary versions","Add TXT or Markdown file","Attachments","Export text","Export audio","Share summary","Playback speed","Move to trash","Edit summary","Draft message"};dialog=new AlertDialog.Builder(this).setTitle("Recording options").setItems(options,(d,index)->{
        switch(index){case 0:prompt("Rename",currentRecord.optString("title"),false,value->patchRecord(json("title",value)));break;
        case 1:chooseResource("folders","Move to folder",true,id->patchRecord(json("folder_id",id.isEmpty()?JSONObject.NULL:id)));break;
        case 2:chooseTags();break;case 3:chooseResource("templates","Summary template",true,id->generateRecord("summaries",id));break;
        case 4:confirm("Transcribe again","A new transcript version will be created from the audio. Earlier edits remain in version history.",()->generateRecord("transcriptions",null));break;
        case 5:summaryHistory();break;case 6:pendingAttachmentId=detailId;pick("attachment");break;case 7:attachments();break;
        case 8:dialog=new AlertDialog.Builder(this).setTitle("Export format").setItems(new String[]{"Markdown","TXT","JSON"},(x,n)->{String format=new String[]{"md","txt","json"}[n];task("Preparing export…",()->api.bytes("GET","/api/v1/recordings/"+detailId+"/exports?format="+format,null),bytes->exportFile("Teno-notes."+format,format.equals("json")?"application/json":"text/plain",bytes));}).show();break;
        case 9:task("Downloading audio…",()->api.bytes("GET","/api/v1/recordings/"+detailId+"/audio",null),bytes->exportFile("Teno-recording.wav","audio/wav",bytes));break;
        case 10:String body=currentSummaries.length()>0?currentSummaries.optJSONObject(0).optJSONObject("data").optString("summary"):"No summary available";share(currentRecord.optString("title")+"\n\n"+body);break;
        case 11:dialog=new AlertDialog.Builder(this).setTitle("Playback speed").setItems(new String[]{"0.75×","1×","1.25×","1.5×","2×"},(x,n)->{speed=new float[]{.75f,1,1.25f,1.5f,2}[n];if(player!=null&&playerReady)try{player.setPlaybackParams(player.getPlaybackParams().setSpeed(speed));}catch(Exception ignored){} }).show();break;
        case 13:editSummary();break;case 14:messageDraft(currentSummaries.length()==0?"":currentSummaries.optJSONObject(0).optJSONObject("data").optString("summary"));break;case 12:confirm("Move to trash","You can restore this recording from Trash within 30 days.",()->task("Moving…",()->api.request("DELETE","/api/v1/recordings/"+detailId,null),r->home()));break;
        }
    }).show();}
    void patchRecord(JSONObject body){task("Saving changes…",()->api.request("PATCH","/api/v1/recordings/"+detailId,body),v->loadDetail(true));}
    void editSegment(JSONObject segment){prompt("Edit transcript",segment.optString("text"),true,value->{JSONObject body=json("revision",currentTranscript.optInt("revision"),"segments",new JSONArray().put(json("id",segment.optString("id"),"text",value)));task("Saving version…",()->api.request("PATCH","/api/v1/recordings/"+detailId+"/transcriptions",body),v->loadDetail(true));});}
    void generateRecord(String kind,String template){JSONObject body=json("client_id",UUID.randomUUID().toString());if(template!=null&&!template.isEmpty())try{body.put("template_id",template);}catch(Exception ignored){}task("Submitting request…",()->api.post("/api/v1/recordings/"+detailId+"/"+kind,body),job->watchJob(job.optString("id"),()->loadDetail(true)));}
    void watchJob(String id,Runnable done){status.setText("Processing. You can return later.");int version=generation;pollJob(id,done,version,0);}
    void pollJob(String id,Runnable done,int version,int tries){if(version!=generation||isDestroyed())return;io.execute(()->{try{JSONObject job=api.get("/api/v1/jobs/"+id);handler.post(()->{if(version!=generation)return;String state=job.optString("status");if(state.equals("completed")){status.setText("Processing complete");done.run();}else if(state.equals("failed")){JSONObject err=job.optJSONObject("error");confirm("Processing failed",err==null?"Try again later":err.optString("message"),()->task("Retrying…",()->api.post("/api/v1/jobs/"+id+"/retry",new JSONObject()),v->watchJob(id,done)));}else if(tries<240){status.setText("Processing"+state(state)+" · You can return later");handler.postDelayed(()->pollJob(id,done,version,tries+1),2500);}else status.setText("Still processing. Refresh to check the latest status.");});}catch(Exception e){handler.post(()->{if(version==generation){status.setText("Status is unavailable. Refresh to try again.");}});}});}
    void summaryHistory(){String[] entries=new String[currentSummaries.length()];for(int i=0;i<entries.length;i++)entries[i]="Version "+(entries.length-i)+" · "+date(currentSummaries.optJSONObject(i).optString("created_at"));dialog=new AlertDialog.Builder(this).setTitle("Summary versions").setItems(entries,(d,i)->{JSONObject data=currentSummaries.optJSONObject(i).optJSONObject("data");alert(data.optString("title"),data.optString("summary"),null);}).show();}
    void attachments(){task("Loading attachments…",()->arr(api.get("/api/v1/recordings/"+detailId+"/attachments"),"items"),items->{if(items.length()==0){alert("No attachments","Add a UTF-8 TXT or Markdown file.",null);return;}String[] names=new String[items.length()];for(int i=0;i<names.length;i++)names[i]=items.optJSONObject(i).optJSONObject("data").optString("title");dialog=new AlertDialog.Builder(this).setTitle("Recording attachments").setItems(names,(d,i)->{JSONObject item=items.optJSONObject(i);dialog=new AlertDialog.Builder(this).setTitle(names[i]).setMessage(item.optJSONObject("data").optString("content")).setPositiveButton("Close",null).setNegativeButton("Delete attachment",(x,w)->confirm("Delete attachment","Future summaries and answers will no longer use this file.",()->task("Deleting attachment…",()->api.request("DELETE","/api/v1/recordings/"+detailId+"/attachments/"+item.optString("id"),null),r->attachments()))).show();}).show();});}
    void chooseTags(){task("Loading tags…",()->arr(api.get("/api/v1/tags"),"items"),tags->{String[] names=new String[tags.length()];boolean[] checked=new boolean[tags.length()];JSONArray previous=arr(currentRecord,"tags");Set<String> ids=new HashSet<>();for(int i=0;i<previous.length();i++)ids.add(previous.optString(i));for(int i=0;i<names.length;i++){names[i]=tags.optJSONObject(i).optJSONObject("data").optString("title");checked[i]=ids.contains(tags.optJSONObject(i).optString("id"));}dialog=new AlertDialog.Builder(this).setTitle("Select tags").setMultiChoiceItems(names,checked,(d,n,v)->checked[n]=v).setPositiveButton("Save",(d,w)->{JSONArray selected=new JSONArray();for(int i=0;i<checked.length;i++)if(checked[i])selected.put(tags.optJSONObject(i).optString("id"));patchRecord(json("tags",selected));}).setNegativeButton("Cancel",null).show();});}

    void releasePlayer(){playerReady=false;if(player!=null){try{player.release();}catch(Exception ignored){}player=null;playerSource="";}}
    void playLocal(JSONObject draft){try{play(draft.getString("path"),0,false);}catch(Exception e){error(e);}}
    void playCloud(String id,int position){task("Preparing audio…",()->api.get("/api/v1/me"),r->play(store.base()+"/api/v1/recordings/"+id+"/audio",position,true));}
    void play(String source,int position,boolean remote){
        try{
            if(player!=null&&source.equals(playerSource)){if(!playerReady)return;if(position>0){player.seekTo(position);player.start();}else if(player.isPlaying())player.pause();else player.start();return;}
            releasePlayer();playerSource=source;player=new MediaPlayer();MediaPlayer p=player;p.setAudioAttributes(new AudioAttributes.Builder().setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).setUsage(AudioAttributes.USAGE_MEDIA).build());
            if(remote){Map<String,String> headers=new HashMap<>();headers.put("Authorization","Bearer "+store.token("access_token"));p.setDataSource(this,Uri.parse(source),headers);}else p.setDataSource(source);
            p.setOnPreparedListener(mp->{if(player!=mp)return;playerReady=true;mp.seekTo(position);mp.setPlaybackParams(new PlaybackParams().setSpeed(speed));mp.start();if(playStatus!=null)playStatus.setText("Playing");});p.setOnErrorListener((mp,w,e)->{releasePlayer();alert("Playback failed","Check your connection and audio file. If your session expired, sign in again.",null);return true;});p.prepareAsync();if(status!=null)status.setText("Preparing audio…");
        }catch(Exception e){releasePlayer();error(e);}
    }

