    void feature(String title,String desc,Runnable action){LinearLayout c=card(content);c.addView(bold(title+"   ›",19,INK));gap(c,6);c.addView(text(desc,13,MUTED));c.setOnClickListener(v->action.run());}
    String kindTitle(String kind){switch(kind){case "tasks":return "Tasks";case "events":return "Events";case "memories":return "Personal memory";case "folders":return "Folders";case "tags":return "Tags";case "templates":return "Summary templates";case "devices":return "Registered devices";case "chats":return "Conversations";default:return kind;}}
    void resources(String kind){resourceKind=kind;begin("resource",kindTitle(kind),"Saved to your account");if(kind.equals("tasks"))buttons(content,"Calendar",()->resources("events"),"Team tasks",this::workspaces);content.addView(button("Add "+kindTitle(kind),true,()->docEditor(kind,null)));if(kind.equals("events"))buttons(content,"Import ICS",()->pick("ics"),"Export ICS",()->task("Preparing calendar file…",()->api.bytes("GET","/api/v1/events/export.ics",null),bytes->exportFile("Teno-calendar.ics","text/calendar",bytes)));task("Syncing…",()->arr(api.get("/api/v1/"+kind+"?limit=200"),"items"),items->{if(items.length()==0){LinearLayout c=card(content);c.addView(text("No items yet. Add one to get started.",15,MUTED));}for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i),data=item.optJSONObject("data");LinearLayout c=card(content);LinearLayout h=row();if(kind.equals("tasks")){CheckBox check=new CheckBox(this);check.setChecked(data.optBoolean("completed"));check.setContentDescription("Complete "+data.optString("title"));check.setOnCheckedChangeListener((b,on)->task("Updating task…",()->api.request("PATCH","/api/v1/tasks/"+item.optString("id"),json("completed",on)),r->{if(on)cancelReminder(item.optString("id"));}));h.addView(check);}h.addView(bold(data.optString("title","Untitled"),17,INK),new LinearLayout.LayoutParams(0,-2,1));c.addView(h);String detail=str(data,"content");if(kind.equals("templates"))detail=str(data,"prompt");if(!detail.isEmpty())c.addView(text(detail,14,MUTED));if(kind.equals("events"))c.addView(text(date(str(data,"starts_at"))+" — "+date(str(data,"ends_at")),13,PRIMARY));if(kind.equals("tasks")&&!str(data,"due_at").isEmpty())c.addView(text("Due "+date(str(data,"due_at")),12,PRIMARY));if(!str(data,"recording_id").isEmpty()){TextView source=text("Open source recording",13,PRIMARY);source.setOnClickListener(v->detail(data.optString("recording_id")));c.addView(source);}buttons(c,"Edit",()->docEditor(kind,item),(kind.equals("tasks")||kind.equals("events"))?"Set reminder":"More",()->{if(kind.equals("tasks")||kind.equals("events"))reminder(item);else resourceMore(kind,item);});}});}
    void resourceMore(String kind,JSONObject item){String[] choices=kind.equals("folders")?new String[]{"Add subfolder","Delete"}:new String[]{"Delete"};dialog=new AlertDialog.Builder(this).setTitle(kindTitle(kind)).setItems(choices,(d,i)->{if(kind.equals("folders")&&i==0){JSONObject child=json("data",json("parent_id",item.optString("id")));docEditor(kind,child);}else deleteResource(kind,item);}).show();}
    void deleteResource(String kind,JSONObject item){confirm("Delete"+kindTitle(kind),"Delete this item? Deleting a folder keeps its recordings in the library.",()->task("Deleting…",()->api.request("DELETE","/api/v1/"+kind+"/"+item.optString("id"),null),r->{cancelReminder(item.optString("id"));if(kind.equals("chats"))chats();else resources(kind);}));}
    void docEditor(String kind,JSONObject item){
        JSONObject data=item==null?new JSONObject():item.optJSONObject("data");if(data==null)data=new JSONObject();final JSONObject old=data;boolean editing=item!=null&&!item.optString("id").isEmpty();
        LinearLayout form=column();form.setPadding(dp(20),0,dp(20),0);EditText title=input(form,"Title",str(data,"title"),false);EditText body=null,due=null,start=null,end=null,assignee=null,color=null,hardware=null;
        if(Arrays.asList("tasks","events","memories").contains(kind))body=input(form,"Details",str(data,"content"),true);
        if(kind.equals("templates"))body=input(form,"Summary instructions",str(data,"prompt"),true);
        if(kind.equals("tasks")){assignee=input(form,"Assignee · Optional",str(data,"assignee"),false);due=input(form,"Due date · YYYY-MM-DD HH:mm · Optional",localTime(str(data,"due_at")),false);}
        if(kind.equals("events")){start=input(form,"Start · YYYY-MM-DD HH:mm",localTime(str(data,"starts_at")),false);end=input(form,"End · YYYY-MM-DD HH:mm · Optional",localTime(str(data,"ends_at")),false);}
        if(kind.equals("folders")||kind.equals("tags"))color=input(form,"Color · For example #20251F",str(data,"color").isEmpty()?"#20251F":str(data,"color"),false);
        if(kind.equals("devices"))hardware=input(form,"Recorder ID",str(data,"hardware_id"),false);
        final EditText fBody=body,fDue=due,fStart=start,fEnd=end,fAssignee=assignee,fColor=color,fHardware=hardware;ScrollView view=new ScrollView(this);view.addView(form);
        AlertDialog edit=new AlertDialog.Builder(this).setTitle((editing?"Edit":"New ")+kindTitle(kind)).setView(view).setNegativeButton("Cancel",null).setNeutralButton(editing?"Delete":null,editing?(d,w)->deleteResource(kind,item):null).setPositiveButton("Save",null).create();dialog=edit;edit.setOnShowListener(d->edit.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String t=title.getText().toString().trim();if(t.isEmpty())throw new IOException("Enter a title");JSONObject payload=json("title",t);if(fBody!=null)payload.put(kind.equals("templates")?"prompt":"content",fBody.getText().toString());if(fDue!=null)payload.put("due_at",isoTime(fDue.getText().toString()));if(fStart!=null){if(fStart.getText().toString().trim().isEmpty())throw new IOException("Enter a start time");payload.put("starts_at",isoTime(fStart.getText().toString()));payload.put("ends_at",isoTime(fEnd.getText().toString()));}if(fAssignee!=null)payload.put("assignee",fAssignee.getText().toString());if(fColor!=null){String col=fColor.getText().toString();Color.parseColor(col);payload.put("color",col);}if(fHardware!=null)payload.put("hardware_id",fHardware.getText().toString());if(!str(old,"parent_id").isEmpty())payload.put("parent_id",old.optString("parent_id"));edit.dismiss();task("Saving…",()->api.request(editing?"PATCH":"POST","/api/v1/"+kind+(editing?"/"+item.optString("id"):""),payload),r->{if(kind.equals("chats"))chats();else resources(kind);});}catch(Exception ex){Toast.makeText(this,friendly(ex),Toast.LENGTH_LONG).show();}}));edit.show();
    }
    String localTime(String iso){try{return OffsetDateTime.parse(iso).atZoneSameInstant(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));}catch(Exception e){return "";}}
    Object isoTime(String value)throws Exception{if(value.trim().isEmpty())return JSONObject.NULL;try{return LocalDateTime.parse(value.trim(),DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toOffsetDateTime().toString();}catch(Exception e){throw new IOException("Use YYYY-MM-DD HH:mm");}}
    interface StringResult{void done(String value);}
    void prompt(String title,String initial,boolean multiline,StringResult callback){LinearLayout c=column();c.setPadding(dp(20),dp(8),dp(20),0);EditText field=input(c,title,initial,multiline);dialog=new AlertDialog.Builder(this).setTitle(title).setView(c).setPositiveButton("OK",(d,w)->callback.done(field.getText().toString())).setNegativeButton("Cancel",null).show();}
    void chooseResource(String kind,String title,boolean empty,StringResult callback){task("Loading options…",()->arr(api.get("/api/v1/"+kind+"?limit=200"),"items"),items->{String[] names=new String[items.length()+(empty?1:0)];if(empty)names[0]="None";for(int i=0;i<items.length();i++)names[i+(empty?1:0)]=items.optJSONObject(i).optJSONObject("data").optString("title");dialog=new AlertDialog.Builder(this).setTitle(title).setItems(names,(d,n)->callback.done(empty&&n==0?"":items.optJSONObject(n-(empty?1:0)).optString("id"))).setNegativeButton("Cancel",null).show();});}
    void reminder(JSONObject item){notificationPermission();prompt("Reminder · Local time",LocalDateTime.now().plusHours(1).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")),false,value->{try{long at=OffsetDateTime.parse(isoTime(value).toString()).toInstant().toEpochMilli();if(at<=System.currentTimeMillis())throw new IOException("Choose a future time");String id=item.optString("id");Intent intent=new Intent(this,ReminderReceiver.class).putExtra("title",item.optJSONObject("data").optString("title")).putExtra("id",id.hashCode()).putExtra("scope",store.scope());PendingIntent pending=PendingIntent.getBroadcast(this,id.hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);alert("Reminder set","Android battery settings may delay reminders. Set them again after restarting the phone.",null);}catch(Exception e){error(e);}});}
    void cancelReminder(String id){PendingIntent p=PendingIntent.getBroadcast(this,id.hashCode(),new Intent(this,ReminderReceiver.class),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(p);p.cancel();}}
    void insights(String kind){begin(kind,kind.equals("insights")?"Insights":"Meeting briefs","Use selected recordings");content.addView(button("Choose recordings",true,()->selectRecordings(ids->{selected.clear();selected.addAll(ids);generateSelected(kind);})));task("Loading results…",()->arr(api.get("/api/v1/"+kind),"items"),items->{for(int i=0;i<items.length();i++){JSONObject data=items.optJSONObject(i).optJSONObject("data");LinearLayout c=card(content);c.addView(bold(data.optString("title"),20,INK));gap(c,8);if(kind.equals("briefings")){c.addView(text(data.optString("briefing"),16,INK));JSONArray qs=arr(data,"questions");for(int j=0;j<qs.length();j++)c.addView(text("• "+qs.optString(j),14,MUTED));}else{JSONArray rows=arr(data,"insights");for(int j=0;j<rows.length();j++){JSONObject x=rows.optJSONObject(j);label(c,x.optString("title"));c.addView(text(x.optString("detail"),15,INK));}}}});}
    void generateSelected(String kind){if(selected.isEmpty()){selectRecordings(ids->{selected.addAll(ids);generateSelected(kind);});return;}prompt(kind.equals("briefings")?"Meeting context and questions":"Focus · Optional","",true,context->task("Preparing analysis…",()->api.post("/api/v1/"+kind,json("recording_ids",new JSONArray(selected),"context",context,"client_id",UUID.randomUUID().toString())),job->watchJob(job.optString("id"),()->insights(kind))));}

    void settings(){begin("settings","Account",store.name()+" · Version 0.3.0");feature("Message drafts","Review text before copying or sharing it.",()->messageDraft(""));feature("Saved context","Manage information you choose to use in answers.",()->resources("memories"));feature("Insights","Review patterns across selected recordings.",()->insights("insights"));feature("Meeting briefs","Prepare a brief from recordings you select.",()->insights("briefings"));feature("Folders and tags","Organize your recordings.",()->{dialog=new AlertDialog.Builder(this).setItems(new String[]{"Folders","Tags"},(d,n)->resources(n==0?"folders":"tags")).show();});feature("Summary templates","Choose a format or create a custom template.",()->resources("templates"));feature("Recorder device","Connection, recording and file import.",this::devices);feature("Local storage","Manage local audio and files waiting to upload.",this::localStorage);feature("Trash","Restore or permanently delete recordings.",this::trash);feature("Usage","View processing and chat activity.",this::usage);feature("Server settings",store.base(),()->serverSettings(false));feature("Preferences","Transcription language and timezone.",this::preferences);feature("Privacy and app information","Review audio processing and available features.",()->alert("About Teno","Phone audio is saved locally. When live transcription is enabled, audio is sent through Teno to Azure Speech while you record. Transcripts are processed to produce summaries and answers.\n\nRecorder file transfer verifies the file before uploading it. Original files remain on the recorder. Wi-Fi transfer, firmware updates, paid subscriptions and external integrations are not included.\n\nAccount tokens and device keys are encrypted with Android Keystore. Azure and model service keys are kept on the server.",null));gap(content,16);content.addView(button("Sign out",false,()->{if(busyAccount())return;confirm("Sign out","Local recordings stay on this phone. Sign in to the same account to upload them later.",()->task("Signing out…",()->{try{api.post("/api/v1/auth/logout",new JSONObject());}finally{store.logout();}return true;},v->{selected.clear();releasePlayer();loginPage();}));}));}
    boolean busyAccount(){if(RecorderService.active||RecorderService.finishing||TransferService.active||JwdService.active||pendingOperations.get()>0){alert("Finish the current action","Finish recording, uploading or connecting the recorder before changing the account or server.",null);return true;}return false;}
    void serverSettings(boolean fromLogin){if(busyAccount())return;prompt("Server address",store.base(),false,value->{try{String url=Api.validateBase(value);if(!url.equals(store.base())){store.logout();store.base(url);selected.clear();}task("Checking connection…",()->api.get("/health/ready"),r->{if(store.token("access_token").isEmpty())loginPage();else settings();});}catch(Exception e){error(e);}});}
    void preferences(){begin("preferences","Preferences","");content.addView(bold("Preferences",27,INK));label(content,"Transcription language");Spinner lang=new Spinner(this);lang.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Chinese (Mandarin)","English (US)"}));lang.setSelection(store.language().equals("en-US")?1:0);content.addView(lang);label(content,"Summary language");Spinner summary=new Spinner(this);summary.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"English","Chinese"}));summary.setSelection(getSharedPreferences("teno",0).getString("summary_language","en-US").equals("zh-CN")?1:0);content.addView(summary);CheckBox live=new CheckBox(this);live.setText("Live transcription by default");live.setChecked(getSharedPreferences("teno",0).getBoolean("live_default",true));gap(content,15);content.addView(live);content.addView(text("The app interface uses English. Recognition follows the language selected above.",13,MUTED));EditText timezone=input(content,"Timezone",ZoneId.systemDefault().getId(),false);gap(content,16);content.addView(button("Save preferences",true,()->{String language=lang.getSelectedItemPosition()==1?"en-US":"zh-CN",summaryLanguage=summary.getSelectedItemPosition()==1?"zh-CN":"en-US";try{ZoneId.of(timezone.getText().toString());}catch(Exception e){alert("Check the timezone","Enter a timezone such as Asia/Shanghai or America/Los_Angeles.",null);return;}task("Saving preferences…",()->api.savePreferences(json("language",language,"summary_language",summaryLanguage,"timezone",timezone.getText().toString())),r->{store.language(language);getSharedPreferences("teno",0).edit().putBoolean("live_default",live.isChecked()).putString("summary_language",summaryLanguage).apply();settings();});}));}

    void devices(){startActivity(new Intent(this,JwdActivity.class));}
    void localStorage(){
        begin("local","Local storage","Local files are stored separately for each account.");JSONArray drafts=store.drafts();long total=0;
        for(int i=0;i<drafts.length();i++)total+=new File(drafts.optJSONObject(i).optString("path")).length();
        content.addView(bold(String.format(Locale.US,"%.1f MB · %d files",total/1048576.0,drafts.length()),22,INK));
        for(int i=0;i<drafts.length();i++){JSONObject d=drafts.optJSONObject(i);LinearLayout c=card(content);c.addView(bold(d.optString("title"),17,INK));c.addView(text(str(d,"recording_id").isEmpty()?"Saved on phone · Not uploaded":"Uploaded · Local copy available",12,MUTED));buttons(c,"Play local copy",()->playLocal(d),"Delete local copy",()->{if(busyAccount())return;confirm("Delete local file",str(d,"recording_id").isEmpty()?"This recording has not been uploaded. Deleting it cannot be undone.":"Only this phone's copy will be deleted. The uploaded recording is kept.",()->{try{releasePlayer();store.deleteDraft(d);localStorage();}catch(Exception e){error(e);}});});}
    }
    void usage(){begin("usage","Usage","App activity, separate from provider billing.");task("Loading usage…",()->new JSONObject[]{api.get("/api/v1/capabilities"),api.get("/api/v1/usage")},data->{LinearLayout c=card(content);c.addView(bold("Service connected",22,GREEN));label(c,"This month · UTC");c.addView(text("Transcription: "+clock(data[1].optLong("azure_audio_ms"))+"\nDeepSeek tokens: "+data[1].optLong("deepseek_tokens"),18,INK));label(c,"Service limits");c.addView(text("File transcription: "+data[0].optString("asr_mode")+"\nLive sessions: "+data[0].optInt("speech_concurrency",1)+"\nFile limit: "+data[0].optInt("max_audio_seconds",7200)/60+" minutes / "+data[0].optLong("max_upload_bytes",262144000)/1048576+" MiB\nPhone recording limit: 54 minutes",14,MUTED));});}
    void trash(){begin("trash","Trash","Restore recordings within 30 days of deletion.");task("Loading trash…",()->arr(api.get("/api/v1/trash"),"items"),items->{if(items.length()==0)content.addView(text("Trash is empty",16,MUTED));for(int i=0;i<items.length();i++){JSONObject r=items.optJSONObject(i);LinearLayout c=card(content);c.addView(bold(r.optString("title"),17,INK));buttons(c,"Restore",()->task("Restoring…",()->api.post("/api/v1/trash/"+r.optString("id")+"/restore",new JSONObject()),v->trash()),"Delete permanently",()->confirm("Delete permanently","The uploaded audio, transcript and generated content will be deleted permanently. Local copies are managed separately.",()->task("Deleting…",()->api.request("DELETE","/api/v1/trash/"+r.optString("id"),null),v->trash())));}});}

    void pick(String kind){pendingImport=kind;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");if(kind.equals("audio"))i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/mp4","application/ogg"});else if(kind.equals("attachment"))i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","text/markdown","text/x-markdown"});startActivityForResult(i,200);}
    void exportFile(String filename,String mime,byte[] data){pendingExport=data;exportMime=mime;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,201);}
    String filename(Uri uri){try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}return "imported.wav";}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
        if(request==201){byte[] bytes=pendingExport;pendingExport=null;if(bytes==null)return;task("Saving file…",()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}return true;},v->alert("Export complete","The file was saved to your selected location.",null));return;}
        if(request!=200)return;String kind=pendingImport;String name=filename(uri);task("Importing file…",()->{
            long limit=kind.equals("audio")?262144000:kind.equals("ics")?1048576:200000;File temp=new File(getCacheDir(),"import-"+UUID.randomUUID());
            try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>limit)throw new IOException("The file exceeds the size limit");out.write(buffer,0,n);}}
            try{
                if(kind.equals("audio")){String ext=name.contains(".")?name.substring(name.lastIndexOf('.')).toLowerCase(Locale.ROOT):".wav";if(!Arrays.asList(".wav",".mp3",".m4a",".ogg",".mp4").contains(ext))throw new IOException("Supported audio: WAV, MP3, M4A and OGG");JSONObject draft=store.newDraft(name,ext);File destination=new File(draft.getString("path"));try(InputStream in=new FileInputStream(temp);OutputStream out=new FileOutputStream(destination)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}store.save(draft);return draft;}
                if(kind.equals("ics"))return api.upload("/api/v1/events/import.ics",temp,name,null,null);
                return api.upload("/api/v1/recordings/"+pendingAttachmentId+"/attachments",temp,name,null,null);
            }finally{temp.delete();}
        },value->{if(kind.equals("audio"))uploadDraft(value);else if(kind.equals("ics"))resources("events");else{alert("Attachment added","Future summaries and answers can use this file. Regenerate an existing summary to include it.",null);loadDetail(true);}});
    }
    void share(String body){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,body);startActivity(Intent.createChooser(i,"Share Teno notes"));}

    ImageView icon(String name,int color){ImageView v=new ImageView(this);int id=getResources().getIdentifier("ic_"+name,"drawable",getPackageName());if(id!=0)v.setImageResource(id);v.setColorFilter(color);return v;}
    View iconButton(String name,String label,Runnable action){ImageView v=icon(name,INK);v.setPadding(dp(11),dp(11),dp(11),dp(11));v.setBackground(shape(Color.WHITE,26));v.setContentDescription(label);v.setFocusable(true);v.setOnClickListener(w->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(44),dp(44));p.setMargins(dp(6),0,0,0);v.setLayoutParams(p);return v;}
    void addContent(){dialog=new AlertDialog.Builder(this).setTitle("Add content").setItems(new String[]{"Record with phone","Record with device","Import from recorder","Import audio file","Create event"},(d,i)->{if(i==0)recordPage();else if(i==1||i==2)devices();else if(i==3)pick("audio");else docEditor("events",null);}).setNegativeButton("Cancel",null).show();}
    void workspaces(){task("Loading workspaces…",()->api.get("/api/v1/team-auth/me"),data->{JSONArray teams=arr(data,"teams");String[] names=new String[teams.length()+2];names[0]="Personal workspace";for(int i=0;i<teams.length();i++)names[i+1]=teams.optJSONObject(i).optString("name");names[names.length-1]="Join with invitation";dialog=new AlertDialog.Builder(this).setTitle("Workspaces").setItems(names,(d,n)->{if(n==0)home();else if(n==names.length-1)startActivity(new Intent(this,TeamActivity.class).putExtra("activate",true));else startActivity(new Intent(this,TeamActivity.class).putExtra("team",teams.optJSONObject(n-1).toString()));}).setNegativeButton("Cancel",null).show();});}
    void updateLive(){if(recordingRetry!=null)recordingRetry.setVisibility(RecorderService.live!=null&&RecorderService.live.gap&&!RecorderService.live.status.startsWith("Live")&&!RecorderService.finishing?View.VISIBLE:View.GONE);if(liveFinal==null)return;LiveTranscriber live=RecorderService.live;if(RecorderService.finishing){liveStatus.setText("Finishing transcript…");return;}if(live==null){liveStatus.setText(RecorderService.paused?"Paused":"Recording · Live transcription off");livePartial.setText("Audio is being saved on this phone.");return;}liveStatus.setText(live.status);StringBuilder text=new StringBuilder();JSONArray parts=live.segments();for(int i=0;i<parts.length();i++){JSONObject p=parts.optJSONObject(i);text.append(clock(p.optLong("start_ms"))).append("\n").append(p.optString("text")).append("\n\n");}String value=text.toString();if(!value.equals(liveRendered)){liveFinal.setText(value);liveRendered=value;}livePartial.setText(live.partial.isEmpty()?(parts.length()==0?"Your transcript will appear here.":""):live.partial+"\nTranscribing…");}
    void saveRecording(String id){try{JSONObject d=store.draft(id);if(d.optString("status").equals("invalid")){begin("save","Recording interrupted","");content.addView(bold("No usable audio saved",25,INK));content.addView(text(d.optString("error","Try recording again."),15,MUTED));content.addView(button("Back to library",true,this::home));content.addView(button("Remove local entry",false,()->{try{store.deleteDraft(d);home();}catch(Exception e){error(e);}}));return;}begin("save","Save recording","");content.addView(bold("Recording saved",27,INK));gap(content,8);content.addView(text(clock(d.optLong("duration_ms"))+" · Saved on this phone",13,MUTED));EditText title=input(content,"Title",d.optString("title"),false);LinearLayout c=card(content);c.addView(text(d.optBoolean("live_complete")?"Live transcript complete":"The full audio will be transcribed after upload.",14,INK));gap(content,16);content.addView(button("Save and continue",true,()->{try{JSONObject current=store.draft(id);current.put("title",title.getText().toString().trim().isEmpty()?"New recording":title.getText().toString());store.save(current);uploadDraft(current);}catch(Exception e){error(e);}}));gap(content,10);content.addView(button("Keep on phone",false,this::home));gap(content,10);content.addView(button("Play audio",false,()->playLocal(d)));JSONArray parts=d.optJSONArray("live_segments");if(parts!=null&&parts.length()>0){label(content,"Transcript");for(int i=0;i<parts.length();i++){JSONObject segment=parts.optJSONObject(i);content.addView(text(clock(segment.optLong("start_ms"))+" · "+segment.optString("text"),15,INK));}}}catch(Exception e){home();}}

    void editSummary(){if(currentSummaries.length()==0){alert("No summary yet","Generate a summary before editing it.",null);return;}JSONObject original=currentSummaries.optJSONObject(0),data=original.optJSONObject("data");String record=detailId;int revision=currentTranscript.optInt("revision");begin("summary_edit","Edit summary","");EditText title=input(content,"Title",data.optString("title"),false),summary=input(content,"Summary",data.optString("summary"),true);StringBuilder lines=new StringBuilder();JSONArray oldPoints=arr(data,"key_points");for(int i=0;i<oldPoints.length();i++)lines.append(oldPoints.optString(i)).append("\n");EditText points=input(content,"Key points · One per line",lines.toString().trim(),true);content.addView(text("Saving keeps the previous summary in version history. Existing action items are preserved.",13,MUTED));String[] request={UUID.randomUUID().toString()},fingerprint={""};gap(content,18);content.addView(button("Save new version",true,()->{JSONArray next=new JSONArray();for(String line:points.getText().toString().split("\\n"))if(!line.trim().isEmpty())next.put(line.trim());String t=title.getText().toString().trim(),body=summary.getText().toString().trim();if(t.isEmpty()||body.isEmpty()){alert("Add a title and summary","Both fields are required.",null);return;}JSONObject payload=json("base_id",original.optString("id"),"revision",revision,"title",t,"summary",body,"key_points",next,"action_items",arr(data,"action_items"));if(!payload.toString().equals(fingerprint[0])){fingerprint[0]=payload.toString();request[0]=UUID.randomUUID().toString();}try{payload.put("client_id",request[0]);}catch(Exception ignored){}task("Saving summary…",()->api.post("/api/v1/recordings/"+record+"/summary-edits",payload),r->detail(record));}));}
    void messageDraft(String initial){begin("message_draft","Draft message","");content.addView(bold("Draft message",27,INK));String key="message_draft_"+store.scope();EditText message=input(content,"Message",initial.isEmpty()?getSharedPreferences("teno",0).getString(key,""):initial,true);message.setMinLines(8);content.addView(text("Review the text and choose where to share it. Teno does not send messages automatically.",13,MUTED));buttons(content,"Save draft",()->{getSharedPreferences("teno",0).edit().putString(key,message.getText().toString()).apply();Toast.makeText(this,"Draft saved",Toast.LENGTH_SHORT).show();},"Share",()->share(message.getText().toString()));gap(content,12);content.addView(button("Copy text",false,()->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Message",message.getText().toString()));Toast.makeText(this,"Copied",Toast.LENGTH_SHORT).show();}));}
